const $=s=>document.querySelector(s);
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved;try{saved=JSON.parse(localStorage.getItem('recompute-v1'))||{plans:[],scenarios:[]}}catch{saved={plans:[],scenarios:[]}};
let page='overview',selected=new Set(assets.map(a=>a.id)),focusAsset=assets[0],query='',filter='all';
const navs=[['overview','◫','Overview'],['fleet','▦','Fleet'],['command','⌘','Fleet Command'],['lab','⌁','What-if Lab'],['market','◉','Market Intelligence'],['outcomes','↗','Outcome Tracking'],['about','⊙','About']];
function persist(){localStorage.setItem('recompute-v1',JSON.stringify(saved))}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function badge(a){return `<span class="badge ${a.route===5||a.route===4?'amber':a.route===2?'blue':''}">${routes[a.route]} ↗</span>`}
function table(list,checks=false){return `<div class="tablewrap"><table><thead><tr>${checks?'<th>Select</th>':''}<th>ASSET / PASSPORT</th><th>HEALTH</th><th>EST. RESALE</th><th>RECOMMENDED ROUTE</th><th></th></tr></thead><tbody>${list.map(a=>`<tr>${checks?`<td><input class="check" type="checkbox" aria-label="Select ${a.id}" data-select="${a.id}" ${selected.has(a.id)?'checked':''}></td>`:''}<td><span class="gpuicon">▥</span><span class="assetname">${a.model}<small>${a.id} &nbsp; ${a.memory}</small></span></td><td><span class="health"><i><b style="width:${a.health}%"></b></i>${a.health}%</span></td><td>${money(a.value)}<small>Illustrative valuation</small></td><td>${badge(a)}</td><td><button class="textlink" data-passport="${a.id}" aria-label="Open passport ${a.id}">Passport ↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No assets match your search.</td></tr>'}</tbody></table></div>`}
const total=assets.reduce((s,a)=>s+a.value,0);
function slider(id,label,value,min,max,step,suffix){return `<label class="control"><span>${label}<b id="${id}Value">${id==='energy'?'$':''}${value}${suffix}</b></span><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" data-suffix="${suffix}"></label>`}
function getLab(){return calculate(focusAsset,+$('#util').value,+$('#energy').value,+$('#days').value,+$('#decline').value)}
function renderComparisons(){$('#comparisons').innerHTML=saved.scenarios.length?saved.scenarios.map((s,i)=>`<div class="outcome row"><div><strong>${esc(s.name)}</strong><small>${s.util}% utilization · $${s.energy}/kWh · ${s.days} days · ${s.decline}% depreciation</small><small>Host ${money(s.host)} / sell ${money(s.sale)}</small></div><button class="textlink" data-remove-scenario="${i}" aria-label="Remove comparison ${i+1}">Remove</button></div>`).join(''):'<p class="subtext">Save a scenario to compare different operating assumptions.</p>'}
function render(){page=location.hash.slice(1)||'home';document.body.classList.toggle('experience-mode',page==='home');if(page==='home'){document.querySelector('#experience').innerHTML=experience();return}if(!navs.some(n=>n[0]===page))page='overview';$('#nav').innerHTML=navs.map(n=>`<a href="#${n[0]}" class="${page===n[0]?'active':''}" ${page===n[0]?'aria-current="page"':''}><span class="navicon">${n[1]}</span>${n[2]}</a>`).join('');$('#crumb').textContent='Workspace / '+navs.find(n=>n[0]===page)[2];$('#main').innerHTML=({overview,fleet,lab,command,market,outcomes,about})[page]();if(page==='lab')updateLab()}
function addPlan(a,r){if(saved.plans.some(p=>p.id===a.id&&!p.done)){return false}let v=calculate(a);saved.plans.push({id:a.id,model:a.model,route:routes[r],expected:[v.sale,v.wait,v.host,v.hybrid,v.harvest,v.repair][r],date:new Date().toLocaleDateString('en-US'),done:false});persist();return true}
function download(){let csv='Asset ID,Model,Memory,Location,Health,Estimated resale USD,Recommendation\n'+assets.map(a=>[a.id,a.model,a.memory,a.site,a.health,a.value,routes[a.route]].join(',')).join('\n');let link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.download='recompute-fleet.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Fleet exported as CSV')}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.passport){passport(t.dataset.passport);return}if(t.hasAttribute('data-close'))$('#passport').close();if(t.id==='export')download();if(t.id==='passportLab'){$('#passport').close();location.hash='lab';if(page==='lab')render()}if(t.id==='planAsset'){let added=addPlan(focusAsset,+$('#routeSelect').value);$('#passport').close();toast(added?'Decision added to your action plan':'This asset already has an active decision');render()}if(t.id==='createPlan'){let count=0;assets.filter(a=>selected.has(a.id)).forEach(a=>{if(addPlan(a,a.route))count++});toast(`${count} decisions added to your action plan`);location.hash='outcomes'}if(t.id==='toggleAll'){selected=selected.size===assets.length?new Set():new Set(assets.map(a=>a.id));render()}if(t.id==='saveScenario'){let v=getLab();saved.scenarios.push({name:focusAsset.model+' · '+focusAsset.id,util:+$('#util').value,energy:+$('#energy').value,days:+$('#days').value,decline:+$('#decline').value,host:v.host,sale:v.sale});persist();renderComparisons();toast('Scenario saved for comparison')}if(t.dataset.removeScenario!==undefined){saved.scenarios.splice(+t.dataset.removeScenario,1);persist();renderComparisons()}if(t.dataset.removePlan!==undefined){let old=saved.plans.splice(+t.dataset.removePlan,1)[0];persist();render();toast('Decision removed');window.lastRemoved=old}if(t.dataset.complete!==undefined){$('#passport').setAttribute('aria-label','Record an outcome');let i=+t.dataset.complete,p=saved.plans[i];$('#passport').innerHTML=`<form id="outcomeForm"><div class="row"><h2>Record the next chapter.</h2><button type="button" class="close" data-close aria-label="Close outcome form">×</button></div><p class="subtext">${esc(p.model)} · ${esc(p.route)} · Planned ${money(p.expected)}</p><label for="actual">Realized net value (USD)</label><input id="actual" type="number" min="0" max="10000000" step="0.01" required style="display:block;width:100%;margin:14px 0" placeholder="Enter actual proceeds after costs"><p class="subtext">Enter proceeds after all costs. This records an outcome; it does not perform a transaction.</p><button class="btn" type="submit">Save outcome</button></form>`;$('#passport').showModal();$('#outcomeForm').onsubmit=ev=>{ev.preventDefault();p.actual=+$('#actual').value;p.done=true;persist();$('#passport').close();render();toast('Outcome recorded')}}if(t.id==='reset'){$('#passport').setAttribute('aria-label','Reset demo workspace');$('#passport').innerHTML=`<h2>Reset this demo workspace?</h2><p class="subtext">This clears your saved decisions and comparisons in this browser.</p><div class="modalactions"><button class="btn secondary" data-close>Keep my work</button><button class="btn" id="confirmReset">Reset demo</button></div>`;$('#passport').showModal()}if(t.id==='confirmReset'){saved={plans:[],scenarios:[]};persist();$('#passport').close();render();toast('Demo workspace reset')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}if(['util','energy','days','decline'].includes(e.target.id))updateLab()});
document.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;render()}if(e.target.id==='labasset'){focusAsset=assets.find(a=>a.id===e.target.value);updateLab()}if(e.target.dataset.select){e.target.checked?selected.add(e.target.dataset.select):selected.delete(e.target.dataset.select);render()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
